var e=1,t=`ch02-guandu`,n=`1.0.0`,r=`曹操不容易`,i=`第二章 · 建安五年 · 官渡断粮`,a=`粮尽只剩一月、许都暗通袁绍——看曹公怎么在十不敌一的绝境里熬出乌巢一把火。`,o=14,s={preset:`guandu-frost`,name:`官渡寒霜 · 孤垒`,themeDir:`guandu-frost`,bgFile:`bg.jpg`,bgOpacity:.44,bgmFile:`bgm.mp3`,bgmOrigFile:`bgm-orig.mp3`,bgmLabel:`官渡 · 寒霜孤垒 8x`,moodRates:{calm:1,tense:.94,fire:.88}},c={narrator:{id:`narrator`,name:`巡营所见`,side:`center`,tone:`neutral`},cao:{id:`cao`,name:`曹操`,role:`司空`,side:`right`,tone:`neutral`},xunyu:{id:`xunyu`,name:`荀彧`,role:`尚书令 · 留守许都`,side:`left`,tone:`info`},xunyou:{id:`xunyou`,name:`荀攸`,role:`军师`,side:`left`,tone:`info`},jiaxu:{id:`jiaxu`,name:`贾诩`,role:`执金吾 · 参谋军事`,side:`left`,tone:`info`},xuyou:{id:`xuyou`,name:`许攸`,role:`袁营夜奔谋士`,side:`left`,tone:`warn`},caohong:{id:`caohong`,name:`曹洪`,role:`护军都尉`,side:`left`,tone:`warn`},yuejin:{id:`yuejin`,name:`乐进`,role:`讨寇校尉`,side:`left`,tone:`fire`},grain_clerk:{id:`grain_clerk`,name:`军粮吏`,role:`管仓主簿`,side:`left`,tone:`warn`},courier:{id:`courier`,name:`驿使`,role:`八百里急递`,side:`left`,tone:`fire`},camp_clerk:{id:`camp_clerk`,name:`后营文吏`,role:`军正司录事`,side:`left`,tone:`neutral`}},l={opening_focus:{type:`string`,initial:`none`,description:`开场定调`},c1_mode:{type:`string`,initial:`none`,description:`案壹书信案处置`},c1_purge:{type:`string`,initial:`none`,description:`案壹清查分支选择`},c2_mode:{type:`string`,initial:`none`,description:`案贰分粮案处置`},c3_mode:{type:`string`,initial:`none`,description:`案叁土山地道处置`},c4_mode:{type:`string`,initial:`none`,description:`案肆许攸夜奔处置`},c5_mode:{type:`string`,initial:`none`,description:`案伍乌巢军议处置`},canon_score:{type:`number`,initial:0,min:0,max:10,description:`合史决断次数`},audit_score:{type:`number`,initial:0,min:0,max:10,description:`谨慎稳守次数`},dirty_count:{type:`number`,initial:0,min:0,max:10,description:`险计权谋次数`},clues_found:{type:`number`,initial:0,min:0,max:20,description:`查实证物次数`},raid_delayed:{type:`boolean`,initial:!1,description:`是否因疑审误了乌巢初夜先机`},raid_abandoned:{type:`boolean`,initial:!1,description:`是否彻底放弃夜袭乌巢`}},u=[{id:`coin`,label:`钱帛`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_coin`,warnText:`行营钱帛已近见底——再拨一笔工料或重赏，连夜巡护军的赏格都要开成空券。`,redlineDesc:`归零即「府库告罄」：军匠散伙、护卫离心，孤垒从账房里率先撑不住。`},{id:`grain`,label:`军粮`,initial:4,max:6,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_grain`,warnText:`官渡余粮已逼红线——实存本不足一月，再多耗一口便要断炊哗营。`,redlineDesc:`归零即「断粮营啸」：釜底见铁、将士饥瘫，未等袁军攻壁已先内溃。`},{id:`troops`,label:`兵力`,initial:5,max:7,warnAt:1,collapseAt:0,collapseEndingId:`E_collapse_troops`,warnText:`可战精锐已贴近警戒线——若再折损或逃亡，纵有高垒深堑也填不满垛口。`,redlineDesc:`归零即「兵力折尽」：前哨打空、垛口无人，只能趁夜弃垒北走南撤。`}],d=`E_collapse_multi`,f=[{id:`yuanshao_siege`,label:`袁军合围`,initial:1,max:6,warnAt:4,overflowEndingId:`E_deadline_overflow`,warnText:`袁军已依沙塠连营十余里逼死官渡外壕！再迟疑拖延下去，等不到生变便要被合围锁死。`}],p=`N00_intro`,m=[{id:`act0`,num:`序`,title:`官渡寒夜`,startNode:`N00_intro`},{id:`act1`,num:`案壹`,title:`暗通书信`,startNode:`N01_case1`},{id:`act2`,num:`案贰`,title:`小斛分粮`,startNode:`N02_case2`},{id:`act3`,num:`案叁`,title:`土山地道`,startNode:`N03_tunnel`},{id:`act4`,num:`案肆`,title:`许攸夜奔`,startNode:`N04_case4`},{id:`act5`,num:`案伍`,title:`夜袭乌巢`,startNode:`N05_case5`}],h={guandu:{id:`guandu`,term:`官渡`,plain:`今河南中牟东北一带，扼汴水与鸿沟交通咽喉。建安五年秋，曹操主力与袁绍十余万大军夹沙塠对峙于此。`,source:`《三国志·武帝纪》「八月，绍连营稍前，依沙塠为屯，东西数十里。公亦分营与相当」`},baima_yanjin:{id:`baima_yanjin`,term:`白马延津`,plain:`建安五年春末夏初，曹操先后在白马斩颜良、延津斩文丑，虽连折袁氏大将，却因兵少粮乏不得不退保官渡长久相持。`,source:`《三国志·武帝纪》建安五年二月至四月条`},yingyang_chenggao:{id:`yingyang_chenggao`,term:`荥阳成皋`,plain:`楚汉相争时刘邦与项羽死守相持的战略锁钥。荀彧以此比喻官渡：彼时势均尚莫肯先退，何况今以大局扼袁绍之喉。`,source:`《三国志·荀彧传》「未若楚、汉在荥阳、成皋间也。是时刘、项莫肯先退，先退者势屈也」`},shifen_juyi:{id:`shifen_juyi`,term:`十分居一`,plain:`荀彧手书名言。曹操实有精兵不过一两万，面对袁绍精卒十余万、东西数十里的压迫，兵力悬殊至极，唯有画地死守待其内变。`,source:`《三国志·荀彧传》「公以十分居一之众，画地而守之，扼其喉而不得进，已半年矣」`},tongsao_shuxin:{id:`tongsao_shuxin`,term:`许下通书`,plain:`袁绍势大时，许都公卿与曹营中人多暗写效忠书信投递河北以留后路。破袁缴获书信后，曹操尽焚不阅，言「当绍之强，孤犹不能自保」。`,source:`《三国志·武帝纪》「及破绍，得许下及军中人书，皆焚之」`},xiaohu:{id:`xiaohu`,term:`缩斛省粮`,plain:`兵少粮尽时压缩日配口粮、熬过断粮窗口的极限调度（《曹瞒传》另载早年征袁术时曾行「小斛散粮」权术）。官渡之秋的真命题，在于如何让仅剩一月的军粮拖过黎明。`,source:`《三国志·武帝纪》「公军粮方尽」及裴注《曹瞒传》`},qiancheng_yifa:{id:`qiancheng_yifa`,term:`千乘一发`,plain:`官渡之战期间曹操令任峻典军器粮运，因袁军骑兵频频钞断粮道，遂改组千辆大车结阵十重围护齐发，方保许都至官渡粮线不断。`,source:`《三国志·任峻传》「贼数钞断，乃千辆一发，十重围护，贼不敢近」`},tushan_gaolu:{id:`tushan_gaolu`,term:`土山高橹`,plain:`袁绍命军士在曹营外堆筑高大土山，并在山顶架起高橹箭楼俯射曹营，曹兵昼夜顶盾而行，营中大惧。`,source:`《三国志·武帝纪》「绍为高橹，起土山，射营中，营中皆蒙楯，众大惧」`},piliche:{id:`piliche`,term:`霹雳车`,plain:`曹操命军匠抢制的重型发石车（抛石机），石块飞坠声震如雷，袁军畏惧而号之为「霹雳车」，一举击破高橹箭楼。`,source:`《三国志·武帝纪》「太祖乃为发石车，击绍楼，皆破，绍众号曰霹雳车」`},changqian:{id:`changqian`,term:`长堑`,plain:`针对袁绍挖掘地道潜袭曹营的攻势，曹操在营垒内侧横掘深长堑沟截断隧道，使袁军地下奇袭彻底落空。`,source:`《三国志·武帝纪》「绍为地道，欲袭太祖营。太祖辄于内为长堑以拒之」`},xizu_yingyou:{id:`xizu_yingyou`,term:`跣足迎攸`,plain:`建安五年十月故友许攸夜奔官渡，曹操听闻后不及穿履赤足迎出营门，抚掌大笑「子远远来，吾事济矣」（《曹瞒传》载操呼其表字作「子卿」）。`,source:`《三国志·武帝纪》裴注引《曹瞒传》及《资治通鉴》卷63`},wuchao:{id:`wuchao`,term:`乌巢`,plain:`距官渡袁绍主营约四十里的核心囤粮重地（故市、乌巢一线），屯有万余乘辎重粮谷，由大将淳于琼率万余众守卫却军纪松懈。`,source:`《三国志·武帝纪》「今袁氏辎重有万余乘，在故市、乌巢，屯军无严备」`},xianmei_yuanqi:{id:`xianmei_yuanqi`,term:`衔枚袁旗`,plain:`夜袭乌巢时，曹操亲率步骑五千人「皆用袁军旗帜，衔枚缚马口」，沿小道穿行敌境，逢盘问便诈称袁公遣兵增防后军。`,source:`《资治通鉴》卷63 建安五年十月条`},zeizai_beihou:{id:`zeizai_beihou`,term:`贼在背后`,plain:`急袭乌巢时袁军援骑杀至背后，诸将恳请分兵迎敌，曹操怒叱「贼在背后，乃白！」全军背水死战终破淳于琼。`,source:`《三国志·武帝纪》「贼急，骑兵在后……公怒曰：『贼在背后，乃白！』士卒皆殊死战，遂大破之」`},zhanghe_gaolan:{id:`zhanghe_gaolan`,term:`张郃高览`,plain:`袁绍账下核心大将。乌巢遭袭时受命猛攻曹洪驻守的官渡本营而久攻不下，又恐遭谋士郭图诬陷，遂烧毁攻具率众降曹，引发袁军全线溃败。`,source:`《三国志·武帝纪》及《张郃传》「郃等闻琼破，遂来降。绍众大溃」`}},g={yuhuan_xu:{id:`yuhuan_xu`,surface:`议欲还许`,decode:`「手里实粮真只剩最后一个月了——荀文若你在许都若不给我递一根撑腰的硬柱子，明天大军就真得拔营退回家去保本。」`,note:`绝境主帅向后方文胆求的不是安慰，而是敢押身家担责的定心丸。`},houying_anjing:{id:`houying_anjing`,surface:`后营安靖`,decode:`「只要搜查的火把还没照到床板底下的密信，保结花名册上每个人都还是誓死效忠司空的干净好人。」`,note:`强敌压境时，人人皆留后路的沉默共识。`},zhizhi_suimo:{id:`zhizhi_suimo`,surface:`足支岁暮`,decode:`「按每人每日半碗掺了麸皮的稀粥硬熬，熬死几成老弱再把口粮匀给精锐，账面上勉强确实能写到腊月。」`,note:`仓曹文书最怕翻开麻袋踢上一脚。`},bujin_suoshou:{id:`bujin_suoshou`,surface:`营中皆蒙楯`,decode:`「连走出帐篷撒泡尿都要头顶盾牌防箭——士卒嘴上不说退字，心里每多顶一天盾牌，腿肚子就软一分。」`,note:`《武帝纪》寥寥五字背后的日夜煎熬。`},yi_yu_sui:{id:`yi_yu_sui`,surface:`尚可支一岁`,decode:`「越是锅里快见底，见了故交越要先往足岁里硬撑面子；虚张声势不是为了骗死他，而是为了听他戳破时那句真话的分量。」`,note:`《曹瞒传》载曹操与许攸深夜讨价还价的真实心理战。`},qunjin_shi:{id:`qunjin_shi`,surface:`屯军无严备`,decode:`「十万大军把全军命脉堆在四十里外，只留喝大酒的淳于琼照看——这哪里是守粮，分明是摆在冷霜地里的无主宝库。」`,note:`荀攸、许攸共同看穿的袁军致命命门。`},dang_gong_benying:{id:`dang_gong_benying`,surface:`攻其本营，彼自败`,decode:`「袁本初舍不得把主力从官渡抽去救粮仓，偏要拿『围魏救赵』赌曹洪守不住营门——恰恰给了我们绝不回头、一刀捅穿乌巢的缝隙。」`,note:`兵法里的「救粮不救垒」，最忌主将两边都舍不得放手。`},gu_zui_wei_zhi:{id:`gu_zui_wei_zhi`,surface:`孤犹不能自保`,decode:`「战前若抓人便是逼着满营连夜反叛；战后再当众把这箱信一把火烧净，当年偷写降书的人便全是死心塌地的自己人。」`,note:`同一匣密信，早掀盖子是内乱，晚烧灰烬是格局。`}},_={ref_xunyu_letter:{id:`ref_xunyu_letter`,title:`荀彧《官渡复书》· 画地而守`,plain:`建安五年秋曹操粮尽欲退许都，荀彧复书以楚汉荥阳成皋相喻，指出十分居一正应扼喉待变，不可先退。`,quote:`公以十分居一之众，画地而守之，扼其喉而不得进，已半年矣。情见势竭，必将有变，此用奇之时，不可失也。`,source:`《三国志·荀彧传》[A]`,leans:`both`,layer:`A`,topic:`战略定力`},ref_burn_letters:{id:`ref_burn_letters`,title:`破袁焚书 · 「孤犹不能自保」`,plain:`官渡相持期间许都及军中多有人暗通袁绍，曹操破绍得书后尽数焚毁不问，以绝后患。`,quote:`及破绍，得许下及军中人书，皆焚之。曰：「当绍之强，孤犹不能自保，而况众人乎！」`,source:`《三国志·武帝纪》[A]`,leans:`A`,layer:`A`,topic:`御下安众`},ref_ration_convoy:{id:`ref_ration_convoy`,title:`军粮方尽与「千乘一发」`,plain:`建安五年八至九月曹军军粮方尽，曹操命任峻以千辆结阵护送官渡粮运，一面压低消耗苦熬待变。`,quote:`公军粮方尽，与荀彧书，议欲还许。……贼数钞断，乃千辆一发，十重围护，贼不敢近。`,source:`《三国志·武帝纪》&《任峻传》[A]`,leans:`both`,layer:`A`,topic:`断粮补给`},ref_piliche:{id:`ref_piliche`,title:`土山地道与霹雳车、长堑`,plain:`袁绍起土山高橹俯射曹营并挖地道夜袭；曹操赶造发石车（霹雳车）击碎箭楼，内掘长堑阻断地道。`,quote:`绍为高橹，起土山，射营中，营中皆蒙楯，众大惧。太祖乃为发石车，击绍楼，皆破，绍众号曰霹雳车。绍为地道，欲袭太祖营。太祖辄于内为长堑以拒之。`,source:`《三国志·武帝纪》[A]`,leans:`A`,layer:`A`,topic:`筑垒攻防`},ref_xuyou_barefoot:{id:`ref_xuyou_barefoot`,title:`许攸夜奔与「跣出迎之」`,plain:`十月审配收捕许攸家眷，许攸弃袁夜奔官渡。曹操闻讯不及穿鞋赤足迎出，问粮真假后定袭乌巢。`,quote:`公闻攸来，跣出迎之，抚掌笑曰：「子卿远来，吾事济矣！」……操曰：「实支一月耳。」`,source:`《三国志·武帝纪》裴注引《曹瞒传》[B]`,leans:`A`,layer:`B`,topic:`用间纳降`},ref_wuchao_raid:{id:`ref_wuchao_raid`,title:`步骑五千袭乌巢 · 贼在背后`,plain:`曹操留曹洪荀攸守营，亲率五千步骑夜袭乌巢。面对袁军援骑在后请分兵之议，斥「贼在背后，乃白」，大破淳于琼，张郃高览遂降。`,quote:`公乃留曹洪、荀攸守营，自将步骑五千人夜往攻琼……贼急，骑兵在后，请分兵拒之。公怒曰：「贼在背后，乃白！」士卒皆殊死战，遂大破之。`,source:`《三国志·武帝纪》[A]`,leans:`A`,layer:`A`,topic:`乌巢决战`}},v=JSON.parse(`{"N00_intro":{"id":"N00_intro","act":"序 · 官渡寒夜","title":"秋霜壁垒与北岸连营","kind":"scene","mood":"calm","refs":["ref_xunyu_letter","ref_ration_convoy"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年九月 · 河南中牟 · 官渡北壁","text":"秋霜已经压白了土墙上的蒿草。自年初{{gloss:baima_yanjin}}连斩颜良、文丑以来，你已率不到两万疲卒画守{{gloss:guandu}}大半年。往北望去，袁绍依沙塠连营东西数十里，篝火像黑夜里倒挂的星海；再回头看自家大营，火灶稀落，连马槽底都只剩掺了干糠的碎豆。"},{"speaker":"narrator","isWalk":true,"walkKicker":"帅帐灯影 · 戌时","text":"案头上摊着仓曹刚呈的实数，旁边压着你前日亲笔写往许都的那封密信。风从帘缝灌进来，油灯火苗晃了晃——刚在信纸上写下「{{subtext:yuhuan_xu}}」四个字时，连你自己都闻见了满帐焦渴的绝境气息。"},{"speaker":"cao","sourceTag":"暗忖","text":"十万对两万，粮道日日被袁骑抄断，许都又流言四起。再不寻一条活路，这官渡的土垒怕要变成孤自己的坟头。外头马蹄响了——可是许都荀文若的回信到了？"}],"next":"N00_xunyu_letter"},"N00_xunyu_letter":{"id":"N00_xunyu_letter","act":"序 · 许都回信","title":"「此用奇之时，不可失也」","kind":"scene","mood":"calm","refs":["ref_xunyu_letter"],"lines":[{"speaker":"courier","sourceTag":"史载","text":"（解开油布竹筒，双手呈上一卷帛书）禀司空！尚书令荀令君八百里密复已至！马跑折了前蹄，小人换马徒步赶进营门！"},{"speaker":"xunyu","sourceTag":"史载","text":"（帛书墨迹如铁）「今军食虽少，未若楚、汉在{{gloss:yingyang_chenggao}}间也。是时刘、项莫肯先退，先退者势屈也。**公以**{{gloss:shifen_juyi}}**之众，画地而守之，扼其喉而不得进，已半年矣。情见势竭，必将有变，此用奇之时，不可失也。**」"},{"speaker":"xunyou","sourceTag":"推演","text":"文若言之切中肯綮！袁绍众虽十万，志大智小、色厉胆薄，又骄矜日久；我们一旦拔寨退许，十万大军顺势碾来，中原腹地再无第二道官渡可守。"},{"speaker":"jiaxu","sourceTag":"推演","text":"（指尖敲了敲案角）话说得痛快，账却还得一笔一笔熬。粮剩一月、人心浮躁、袁营土山越堆越高——司空若定下死守，底下这几桩随时能炸营的急务，今夜便要亲手先按住。"}],"choices":[{"id":"stance_hold","label":"【定调 · 画地死守】依荀彧之议：十分居一亦死扼官渡咽喉，绝不言退","hint":"定心守垒 · 进入案壹","isBait":true,"stampKind":"approve","stampText":"画地死守","replyText":"文若教孤「扼其喉而不得进」，孤便把这条命钉在官渡北垒上！传令诸营：自今日起，敢再言退保许都者，斩！先呈后营安靖与驿道巡查卷宗！","effects":[{"kind":"var_set","var":"opening_focus","value":"hold"},{"kind":"var_add","var":"canon_score","delta":1}],"next":"N01_case1"},{"id":"stance_conserve","label":"【定调 · 慎守留路】一面死守官渡，一面严核内奸粮数并预整许都归途","hint":"步步核实 · 进入案壹","stampKind":"reject","stampText":"慎守核实","replyText":"文若坐镇许都自然看大势，官渡锅里有没有米却是孤每夜亲眼盯着。既要守，便先把营内营外每一本账核得滴水不漏——传军正司上堂！","effects":[{"kind":"var_set","var":"opening_focus","value":"conserve"},{"kind":"var_add","var":"audit_score","delta":1}],"next":"N01_case1"}]},"N01_case1":{"id":"N01_case1","act":"案壹 · 暗通袁绍书信案","title":"《后营安靖保结》与七封密信","kind":"scene","mood":"tense","refs":["ref_burn_letters"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"巡营所见 · 子夜 · 后营马厩与西哨驿道","text":"你披着黑衣绕出中军，亲自沿马厩巡到西哨。寒霜把马粪冻成硬块，巡夜校尉早缩进帐里烤火。你在草料槽夹层与一名滞留驿卒的鞍袋底摸出**七封火漆未干的密信**——笔迹分明出自许都几位留守公卿与后营两名督粮校尉，信尾压着许都少府旧印余泥与袁军哨卡通行竹符。","clues":[{"id":"clue_secret_letters","label":"鞍袋夹层搜出七封许都公卿与营官私通袁绍密信"},{"id":"clue_stamp_wax","label":"信封压有许都官印余泥及袁营哨卡通行竹符"}]},{"speaker":"camp_clerk","sourceTag":"拟写","text":"（双手呈上《后营安靖保结》，神色恭谨）禀司空！今夜各营巡检已毕，许都留守文武及后营校尉皆矢志效忠，实属{{subtext:houying_anjing}}；西哨驿道更是盘查严密，绝无片纸私出！请司空批示存档。"},{"speaker":"xunyou","sourceTag":"推演","text":"（扫了你袖口一眼，声音压到极低）袁绍十万压在面前，人皆自危，{{gloss:tongsao_shuxin}}怕不止这七封。眼下大敌当前，是当众按名拿人立威、还是先把盖子死死按住？"},{"speaker":"cao","sourceTag":"暗忖","text":"袖子里揣着这七封能掉十颗脑袋的信，案头上却摊着一张写满「安靖无事」的保结。先把这纸鬼话里的两处破绽戳破，再定拿不拿这把刀。"}],"interaction":{"type":"counter_case","title":"帅案核验","docTitle":"《后营安靖保结》","prompt":"用刚才在马厩与西哨搜出的证物，点破保结里的两句虚言：","minExpose":2,"claims":[{"id":"c1_loyal","surface":"「营中将校与许都留守官吏素怀忠义，无一人私通河北书信。」","proof":"你袖中正攥着刚从马槽夹层截获的七封密信——上头有许都公卿的问安辞，也有后营督粮校尉自报营垒虚实的亲笔字迹。","requiredClueId":"clue_secret_letters","effects":[{"kind":"var_add","var":"clues_found","delta":1}]},{"id":"c1_patrol","surface":"「西哨驿道盘查滴水不漏，昨夜子时绝无私带文书与敌符之人出入。」","proof":"驿卒鞍袋里搜出的火漆印泥还没硬透，旁边明晃晃别着一枚袁营夜哨通行竹符——人若真盘查了，竹符怎会留在鞍袋里？","requiredClueId":"clue_stamp_wax","effects":[{"kind":"var_add","var":"clues_found","delta":1}]}]},"choices":[{"id":"approve","label":"【暂压不发 · 密封待焚】七信锁入铁匣秘而不宣，留待破袁后尽焚以稳军心","hint":"钱帛 -1 · 袁军合围 +1","isBait":true,"stampKind":"approve","stampText":"密封待焚","replyText":"保结照准存档！至于这七封信——先封进孤的铁匣锁死，外头半个字不许泄！派心腹暗赐赏帛换防西哨把门盯紧，其余人等，等孤破了袁本初再论！","effects":[{"kind":"var_set","var":"c1_mode","value":"seal"},{"kind":"var_add","var":"canon_score","delta":1},{"kind":"resource","resource":"coin","delta":-1,"reason":"密赐心腹校尉重赏换防西哨、外松内紧封锁驿道"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"秘而不宣稳住内营，袁军外围游骑趁夜略前逼近"}],"next":"N01_branch_seal"},{"id":"reject","label":"【连夜清查 · 按名拿问】即刻封营锁拿涉信将吏，彻查许都往来内鬼","hint":"兵力 -1 · 袁军合围 +1","stampKind":"reject","stampText":"连夜清查","interestNote":"代价：战前大索必致营内人人自危、关联部曲惊散减员，外垒警戒亦滞后","replyText":"敌在墙外，虫已蛀在梁柱里了！传军正司与许褚虎卫连夜封锁后营，把这七封信上的名字一个个提出来审——今夜不把内鬼挖绝，明日谁替孤守辕门？","effects":[{"kind":"var_set","var":"c1_mode","value":"purge"},{"kind":"var_add","var":"audit_score","delta":1},{"kind":"resource","resource":"troops","delta":-1,"reason":"连夜拿问涉信将校引发后营惊扰逃散减员"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"营内彻夜搜查顾此失彼，袁军趁隙前推鹿角"}],"next":"N01_branch_purge"},{"id":"dirty","label":"【假信反钓 · 嫁祸袁营】按原笔迹伪造回信放行，诱袁绍自疑内部反目","hint":"钱帛 +0 · 袁军合围 +0（中盘有离心反噬）","stampKind":"dirty","stampText":"假信反钓","interestNote":"代价：以伪书嫁祸虽乱敌耳目，然左右幕僚见司空亦敢仿书设阱，许攸奔营时将生重嫌","replyText":"既然有竹符，何不替袁本初再添几封热闹信？仿照笔迹重封密函放那驿卒出营，字里顺便『问候』一下田丰与审配的旧怨——叫袁绍自己先在河北抓内鬼！","effects":[{"kind":"var_set","var":"c1_mode","value":"fake_letter"},{"kind":"var_add","var":"dirty_count","delta":1},{"kind":"dirty_trick","id":"dt_fake_letters","label":"仿写密信反钓袁营","interest":"帐下亲信忌惮连自己笔迹亦可被仿造陷害，故人夜奔时护卫离心重赏难安"},{"kind":"debt","debt":{"id":"debt_fake_letters","dueAt":"N04_case4","label":"假信余波反噬","text":"此前仿书设阱的旧事在营中暗流发酵——亲信门吏皆畏罪自保、西门哨卒趁夜逃散，不得不急发重赏补齐内帐戒备。","effects":[{"kind":"resource","resource":"coin","delta":-1,"reason":"加发重赏安抚猜忌动摇的内帐心腹"},{"kind":"resource","resource":"troops","delta":-1,"reason":"寒夜疑惧致后营守卒暗中散失"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"内营疑心令外哨巡检松懈、袁军垒线前移"}]}}],"next":"N01_branch_seal"}]},"N01_branch_seal":{"id":"N01_branch_seal","act":"案壹支线 · 锁匣无声","title":"风声压进铁匣底","kind":"scene","mood":"calm","refs":["ref_burn_letters"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"官渡帅帐 · 丑时","text":"后营文吏捧着盖好大印的保结退下时，手腕直抖却一句话没敢问。西哨换上重赏过的心腹老兵后，今夜再没一只飞鸟悄悄溜出营门。"},{"speaker":"cao","when":{"var":"c1_mode","op":"==","value":"seal"},"sourceTag":"史载","text":"（合上铜锁，轻叹）{{subtext:gu_zui_wei_zhi}}——眼下袁本初十万大军压境，连孤自己都夜夜睡不安稳，何况许都那些捧着朝服讨饭吃的文官？信锁在这里，人先给孤留着。"},{"speaker":"jiaxu","when":{"var":"c1_mode","op":"==","value":"fake_letter"},"sourceTag":"推演","text":"（盯着桌上剩余的印泥）假信确能搅浑袁营的水，只是司空以后写手谕时，底下人接纸的手怕都要比平时凉三分。这笔账，中盘自会找回来。"},{"speaker":"caohong","sourceTag":"推演","text":"明公，后营算是暂且压住了——可刚天明，管仓的主簿在帐外跪了半个时辰，只说今秋军粮实数再瞒不住了。"}],"next":"N02_case2"},"N01_branch_purge":{"id":"N01_branch_purge","act":"案壹支线 · 火把照营","title":"半夜拿人，满营寒噤","kind":"scene","mood":"tense","refs":["ref_burn_letters"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"后营校场 · 四更","text":"火把瞬间照亮半座大营。涉案的驿卒和一名督粮小校被五花大绑按在雪霜地里，周围帐篷帘子后头无数双眼睛静悄悄偷看——谁也不知道下一个被念出名字的会不会是自己亲戚。"},{"speaker":"caohong","sourceTag":"推演","text":"司空，两名小校的部曲刚才趁乱往南面跑了十几个，许都那边听闻风声怕也要震动。剩下这几封牵连侍中、郎官的信，是杀鸡儆猴只诛驿卒便罢，还是顺藤摸瓜连坐到底？"},{"speaker":"xunyou","sourceTag":"推演","text":"再深挖下去，怕连护军各营都要人人自危。请司空早断。"}],"choices":[{"id":"purge_mercy","label":"【诛首止问 · 当众焚书】只斩私递信件的驿卒一人，余书当场付炬安众","hint":"钱帛 -1 · 止血安营","stampKind":"approve","stampText":"诛首焚余","replyText":"祸起贪财通敌的驿卒，余者皆系一时糊涂！当众把那几封信丢进炭盆烧干净，再赐帛抚慰受惊诸营——从此谁敢旧事重提，以造谣论处！","effects":[{"kind":"var_set","var":"c1_purge","value":"mercy"},{"kind":"resource","resource":"coin","delta":-1,"reason":"赐帛安抚受惊后营部曲平息风波"}],"next":"N02_case2"},{"id":"purge_strict","label":"【连坐彻查 · 抄产充军】按名革职抄没私财充军，涉案亲随贬入死士营","hint":"钱帛 +1 · 兵力 -1","stampKind":"reject","stampText":"连坐抄产","replyText":"慈不掌兵！把涉信校尉一并革职查办，抄出私蓄充入军库，连带亲随一律编入前哨掘壕赎罪——军法立在这里，看谁还敢心怀两端！","effects":[{"kind":"var_set","var":"c1_purge","value":"strict"},{"kind":"resource","resource":"coin","delta":1,"reason":"抄没涉案将吏私帛充入军库"},{"kind":"resource","resource":"troops","delta":-1,"reason":"株连严查逼使更多边缘士卒连夜弃营逃散"}],"next":"N02_case2"},{"id":"whatif_fake_defect","label":"【架空】密信不烧也不杀：逼通袁将校发出假约降书，诱袁军夜袭入伏","hint":"平行世界线 · 借内鬼反钓袁绍","stampKind":"dirty","stampText":"钓袁","replyText":"想活命吗？按孤念的字给袁本初写封回信——就说三更开西门献首，孤在营里摆好火坑等他！","effects":[{"kind":"deadline","deadline":"yuanshao_siege","delta":-1,"reason":"借假内应主动打乱袁军围城节奏"}],"next":"N_WI_fake_defect"}]},"N02_case2":{"id":"N02_case2","act":"案贰 · 官渡小斛分粮案","title":"《秋粮实存与支发簿》","kind":"scene","mood":"tense","refs":["ref_ration_convoy"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"巡营所见 · 卯时 · 后营军粮大廒","text":"天光刚泛鱼肚白，你掀开官渡主粮廒的草帘，一股刺鼻的陈糠潮味扑面而来。墙角木架旁新添了几只**削矮二寸的木斛**，斛底黑墨印着「七折量」；再往里屋走，墙根堆着三百多只鼓囊囊的麻袋——你拔出佩剑划开最底下一只，流出来的不是粟米，而是**干燥麦秸混着黄沙**！实打实能入锅的精粟，掰着指头算也撑不过一个月。","clues":[{"id":"clue_small_measure","label":"仓棚木架暗藏削矮二寸、底刻「七折量」的新制小斛"},{"id":"clue_empty_sacks","label":"里排三百麻袋全填麦秸黄沙，实粮不足一月"}]},{"speaker":"grain_clerk","sourceTag":"拟写","text":"（颤巍巍捧上《秋粮实存与支发簿》）禀司空！托任峻将军{{gloss:qiancheng_yifa}}护运之功，各营俱按足斗常制支发，后仓尚存干粟数万斛，{{subtext:zhizhi_suimo}}，绝无断炊之忧！"},{"speaker":"yuejin","sourceTag":"推演","text":"（按住刀柄冷哼）前线弟兄这几日吃的是掺榆皮豆渣的稀粥，裤腰都往里勒了两寸！账簿却还敢写『足斗饱满』，真当底下拿刀的人舌头尝不出味儿？"},{"speaker":"cao","sourceTag":"暗忖","text":"真粮只剩一月，粮吏偏想拿沙袋撑门面。先把这本粉饰账簿上的两处假数点破，再定官渡这最后一锅米怎么分。"}],"interaction":{"type":"counter_case","title":"帅案核验","docTitle":"《秋粮实存与支发簿》","prompt":"用刚才在粮廒亲见的木斛与麻袋证物，戳穿粮簿上的两处瞒报：","minExpose":2,"claims":[{"id":"c2_measure","surface":"「各营均依汉制足斗按日支发，升合无亏，士卒日食饱满。」","proof":"仓棚木架边刚削好的「七折量」小斛墨迹还没干透——你早就在暗地里拿小斛给前营打折发粥了，还敢在账上写足斗？","requiredClueId":"clue_small_measure","effects":[{"kind":"var_add","var":"clues_found","delta":1}]},{"id":"c2_stock","surface":"「后仓实存军粮充裕，纵相持至岁暮腊月亦万无断炊之虞。」","proof":"里屋那三百只撑门面的大麻袋里全是麦秸和沙土！扒开假袋细数，全营真能下锅的军粮最多只够撑一个月！","requiredClueId":"clue_empty_sacks","effects":[{"kind":"var_add","var":"clues_found","delta":1}]}]},"choices":[{"id":"approve","label":"【小斛紧配 · 咬牙死守】核实余粮不足一月，严行{{gloss:xiaohu}}减配硬拖待变","hint":"军粮 -1 · 袁军合围 +1","isBait":true,"stampKind":"approve","stampText":"小斛死守","replyText":"那三百袋沙子连夜拖出去填壕！实粮只剩一月，按足额吃十日便要全军断炊——传令：明日起全营统一用七折小斛秘配，主将与士卒同食粗糠粥！谁敢私藏一升精米，军法斩首！","effects":[{"kind":"var_set","var":"c2_mode","value":"small_hu"},{"kind":"var_add","var":"canon_score","delta":1},{"kind":"resource","resource":"grain","delta":-1,"reason":"剔除虚数沙袋后按一月紧配实数入账"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"节衣缩食勉强拖延时日，袁军合围日渐勒紧"}],"next":"N02_branch_small_hu"},{"id":"reject","label":"【如实公摊 · 亲同甘苦】焚毁小斛亮明实数，撤去减膳按常制均摊熬冬","hint":"军粮 -2 · 袁军合围 +1","stampKind":"reject","stampText":"如实公摊","interestNote":"代价：不肯短秤透支军心，军粮余量将急剧探底，且外围防务难借瞒报拖延","replyText":"打仗哪有拿小斛哄自家弟兄的道理？把七折小斛当众劈了烧火！实数就剩一个月，孤亲自撤了案头肉食与三军同分真粮——吃光以前，大家凭本事杀出一条活路！","effects":[{"kind":"var_set","var":"c2_mode","value":"honest"},{"kind":"var_add","var":"audit_score","delta":1},{"kind":"resource","resource":"grain","delta":-2,"reason":"废止缩斛按实额均摊日粮，余粮加速见底"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"粮尽实情传开后营盘稳重而节奏偏缓，袁军进逼"}],"next":"N02_branch_honest"},{"id":"dirty","label":"【强征世族 · 搜括许颍】密遣精骑驰回许颍强征豪强坞堡私粮充军","hint":"军粮 +1 · 钱帛 -1（夜袭前夕必断后勤）","stampKind":"dirty","stampText":"强征私粮","interestNote":"⚠ 代价：强抄许颍世族私仓虽得现粮，但后方豪强与留守官吏怨恨断供，乌巢前夜必报复截援","replyText":"许颍大族窖里堆着陈年好米，官渡士卒却在啃草根？挑五百精骑驰回后方，凡私藏粟麦不献者以通袁抄没！先救眼前这一口锅再说！","effects":[{"kind":"var_set","var":"c2_mode","value":"levy_gentry"},{"kind":"var_add","var":"dirty_count","delta":1},{"kind":"resource","resource":"grain","delta":1,"reason":"强征许颍世族坞堡藏粮急运官渡"},{"kind":"resource","resource":"coin","delta":-1,"reason":"遣骑兵押运及弹压后方庄园额外耗费"},{"kind":"dirty_trick","id":"dt_levy_gentry","label":"强征许颍世族私粮","interest":"许颍士族怀恨在心，乌巢夜袭前夜联手截留护军冬衣与补给车队"},{"kind":"debt","debt":{"id":"debt_levy_gentry","dueAt":"N05_case5","label":"许颍世族断供报复","text":"被强抄私仓的许颍大族暗中延宕后方押运，冬衣、箭矢与续命粮队迟迟未到官渡，留营一时粮帛俱紧。","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"世族暗中截留延误官渡后续粮队"},{"kind":"resource","resource":"coin","delta":-1,"reason":"高价向行商紧急采买箭羽冬炭补缺"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"后方补给吃紧致使袁军加紧前哨围困"}]}}],"next":"N02_branch_small_hu"}]},"N02_branch_small_hu":{"id":"N02_branch_small_hu","act":"案贰支线 · 灶边薄粥","title":"勒紧腰带熬霜夜","kind":"scene","mood":"tense","refs":["ref_ration_convoy"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"数日后 · 官渡前营火灶","text":"辰时的风把炊烟压在地上散不开。乐进端着一只缺了角的陶碗蹲在战壕边，碗里稀粥飘着几片发黑的榆树皮；周围士卒咽下口水，谁也没再抱怨——司空帐前挂出来的那口铁锅，煮的也是同一锅糠粥。"},{"speaker":"yuejin","when":{"var":"c2_mode","op":"==","value":"small_hu"},"sourceTag":"推演","text":"粮虽只剩一月，照这么一勺一勺往嘴里抠，全营好歹把脊梁骨撑住了。只是弟兄们饿着肚子，袁军那边这几日却像起了大动静……"},{"speaker":"xunyou","when":{"var":"c2_mode","op":"==","value":"levy_gentry"},"sourceTag":"推演","text":"后方抢运来的粟车虽解了眼下饥渴，荀令君今晨却飞书急告：许颍几家大姓已联名上表叫苦，往后护军冬炭与箭羽怕不会再痛快过关了。"}],"next":"N03_tunnel"},"N02_branch_honest":{"id":"N02_branch_honest","act":"案贰支线 · 当众劈斛","title":"碗里实米多三分，仓底见底快一倍","kind":"scene","mood":"cold","refs":["ref_ration_convoy"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"数日后 · 官渡仓场","text":"七折小斛劈成的碎木片在灶膛里烧得噼啪作响。士卒们真盛到了足额的粗粟干饭，眼睛里一下子有了光；可站在空了一大半的后仓门前，管仓主簿算盘拨得越响，额头上的冷汗越多。"},{"speaker":"caohong","sourceTag":"推演","text":"大伙儿倒真服司空这手减膳同食！只是真按足额发下去，任峻的千乘粮队再赶不上来，十来天后咱们怕真得拿马鞍皮煮汤了。"},{"speaker":"jiaxu","sourceTag":"推演","text":"军心既不肯虚耗，外头便须在二十日内见分晓。听！北面垒墙上怎么一阵乱响？"}],"next":"N03_tunnel"},"N03_tunnel":{"id":"N03_tunnel","act":"案叁 · 土山箭楼与掘地道","title":"建安五年秋末 · 天上飞矢，地下挖土","kind":"scene","mood":"tense","refs":["ref_piliche"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年十月初 · 官渡北垒","text":"「笃、笃、笃！」三支带倒钩的雕翎箭猛地钉进帅帐门柱，木屑溅到你靴面上。袁绍在营外连夜堆起了数座高耸{{gloss:tushan_gaolu}}，弓弩手站在半空往下泼雨般攒射——全营士卒如今走路都要头顶木盾，可谓{{subtext:bujin_suoshou}}。更瘆人的是你贴耳听去，**脚底冻土里竟然隐约传来铁镐刨石的闷响**！"},{"speaker":"caohong","sourceTag":"史载","text":"明公！袁军白天站在土山高橹上往营里盲射，弟兄们连锅灶都生不起火；夜里审配又派死士顺着沙土层往咱们营心**挖掘地道**！外墙守卒已死伤数十，营中大惧！"},{"speaker":"yuejin","sourceTag":"推演","text":"若放任袁军把土山推近、地道通到中军帐底，不等粮尽，明天咱们就得在自己营里被袁兵前后夹杀！可要造重器截地道，不仅要拆车毁屋找硬木，还要调动饿着肚子的兵卒昼夜冒矢抢工！"},{"speaker":"xunyou","sourceTag":"推演","text":"要反制，便须拆营造发石重车砸碎高橹、再在营内深掘横堑切断地道；若舍不得这笔血本，便只能主动放弃外垒退缩中军避箭——请司空决断！"}],"choices":[{"id":"counter","label":"【造{{gloss:piliche}} · 掘{{gloss:changqian}}截之】拆大车赶造发石车轰碎土山，内掘长堑断地道","hint":"钱帛 -1 · 兵力 -1 · 袁军合围 +1","isBait":true,"stampKind":"approve","stampText":"霹雳破楼","replyText":"他堆土山，孤便砸碎他的土山！把后营破损辎重车的硬木车轴全拆了，连夜赶制发石车对准高橹狂轰！再挑精壮顶盾于外垒内侧深掘三丈长堑——看他袁军的地道往哪儿钻！","effects":[{"kind":"var_set","var":"c3_mode","value":"counter"},{"kind":"var_add","var":"canon_score","delta":1},{"kind":"resource","resource":"coin","delta":-1,"reason":"拆车征料赶制发石车铁件及犒赏工匠"},{"kind":"resource","resource":"troops","delta":-1,"reason":"士卒顶盾冒矢昼夜抢掘长堑损伤减员"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"攻防胶着期间袁军仍借人数优势继续勒紧包抄"}],"next":"N03_branch_counter"},{"id":"shrink","label":"【弃外垒缩中军 · 省力熬冬】避开土山射程放弃外围土墙，缩守内寨节省工费","hint":"钱帛 +0 · 兵力 +0 · 袁军合围 +2","stampKind":"reject","stampText":"弃壁缩营","interestNote":"代价：退让外垒将令袁军土山前推百步，合围死线剧增至危急边缘","replyText":"粮少兵寡，哪经得起跟十万人在外墙硬拼消耗？全军连夜拆撤外围鹿角，退入中军内寨拉远射程——先保住钱帛和士卒筋骨再图后手！","effects":[{"kind":"var_set","var":"c3_mode","value":"shrink"},{"kind":"var_add","var":"audit_score","delta":1},{"kind":"deadline","deadline":"yuanshao_siege","delta":2,"reason":"弃外垒后撤致使袁军土山高橹全线前推压死内寨"}],"next":"N03_branch_shrink"},{"id":"whatif_retreat_xudu","label":"【架空】真的弃垒退保许都，诱袁绍深入中原","hint":"切入平行历史线 · 放弃官渡孤垒","stampKind":"reject","stampText":"退许","replyText":"文若劝我莫退，可官渡再守下去只剩空壳！传令三更拔营，留空垒给袁本初，全军退保许都！","effects":[{"kind":"resource","resource":"grain","delta":1,"reason":"回靠许都大仓，暂解前线断炊死局"},{"kind":"deadline","deadline":"yuanshao_siege","delta":-1,"reason":"主动跳出官渡合围圈，战线重新拉开"}],"next":"N_WI_xudu_march"}]},"N03_branch_counter":{"id":"N03_branch_counter","act":"案叁支线 · 雷霆破橹","title":"一声霹雳震破敌胆，两军皆入灯枯时","kind":"scene","mood":"tense","refs":["ref_piliche"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"数日后 · 官渡北垒","text":"二十余架沉重的发石车绞紧牛筋巨索，一声梆响，磨盘大的石块呼啸着砸向袁军高橹！「咔嚓」巨响连绵不绝，木楼连人带箭手一齐塌进土山；袁兵惊呼「霹雳车」而乱窜。与此同时，十几名摸出沙壁的袁军掘道兵一头栽进曹军内侧注满泥水的长堑，被长矛按在泥里再没上来。"},{"speaker":"yuejin","sourceTag":"史载","text":"（擦去额角血渍大笑）土山破了，地道也堵死了！可袁绍不肯退兵，仗着人多把包围圈又往两翼铺宽了五里——咱们如今虽守住了壁垒，外头的路却更窄了。"},{"speaker":"cao","sourceTag":"暗忖","text":"守是守住了，可粮仓快见底、外围合围已逼近红线。文若说『情见势竭，必将有变』——袁营里那个裂口，到底什么时候才肯裂开？"}],"next":"N04_case4"},"N03_branch_shrink":{"id":"N03_branch_shrink","act":"案叁支线 · 外垒失守危机","title":"你退一步，土山就进百步","kind":"scene","mood":"fire","refs":["ref_piliche"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"次日黄昏 · 官渡内寨","text":"才退入内寨不到一天，袁军便占了你弃下的外垒土墙，连夜把土山和高橹往前推了整整一百步！带着硫磺松脂的火箭「嗖嗖」越过内墙，直接扎在后仓草棚顶上！"},{"speaker":"caohong","sourceTag":"推演","text":"明公！内寨空间太窄，发石车已经来不及立架了！再这么被居高临下烤两天，不用袁军攻营，粮棚与马厩先要烧个精光！"},{"speaker":"jiaxu","sourceTag":"推演","text":"此刻要么派死士趁黑攀烧最近两座土山以血换气，要么全营挖掘深坑地窖硬扛消耗——两步都是拿肉往刀口上撞，司空快择其一！"}],"choices":[{"id":"shrink_counterattack","label":"【乐进夜斫土山】挑死士趁黑死扑前推土山放火毁橹，以血换一线喘息","hint":"兵力 -2 · 军粮 -1 · 袁军合围 -1","stampKind":"approve","stampText":"夜斫土山","replyText":"绝不能任他把箭楼架在头顶！乐进领死士三百夜袭火烧最近两座土山，毁其高橹再退回！","effects":[{"kind":"resource","resource":"troops","delta":-2,"reason":"夜袭攀攻袁军土山死士血战折损"},{"kind":"resource","resource":"grain","delta":-1,"reason":"火袭波及内寨前哨散失部分干粮"},{"kind":"deadline","deadline":"yuanshao_siege","delta":-1,"reason":"烧毁前推高橹暂时迟滞袁军合围"}],"next":"N04_case4"},{"id":"shrink_turtle","label":"【深挖地窟硬扛】全营缩入覆木土窟死扛箭雨，拿钱粮磨过这一关","hint":"钱帛 -1 · 军粮 -1 · 袁军合围 +1","stampKind":"reject","stampText":"地窟硬扛","replyText":"拆营门木板盖地窟！全营昼伏夜出躲避矢石，绝不再出垒平白送命——熬到袁绍自己缺粮撤兵！","effects":[{"kind":"resource","resource":"coin","delta":-1,"reason":"征购木料生牛皮加固掩体顶棚"},{"kind":"resource","resource":"grain","delta":-1,"reason":"困守地窟烧损潮湿口粮并耗尽备粮"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"缩入地窟彻底让出地面主动权，袁军合围更甚"}],"next":"N04_case4"}]},"N04_case4":{"id":"N04_case4","act":"案肆 · 许攸赤足夜奔","title":"《许子远献乌巢密报》","kind":"scene","mood":"tense","refs":["ref_xuyou_barefoot"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"巡营所见 · 建安五年十月夜 · 北门哨卡","text":"寒风卷着枯草敲打辕门。你刚走近北门栅栏，便见一名披散长发的中年文士牵着一匹汗气蒸腾的瘦马伏在吊桥外——他只穿单袍，连佩剑与印绶都没有带齐，鞋帮上糊着厚厚的河北黑泥霜。另一边，邺城暗探昨夜传回的一片绢条刚好折在你掌心：**审配在邺城以贪墨犯法之名收捕了袁营谋士许攸的妻子家眷。**","clues":[{"id":"clue_frost_mud","label":"来人单衣无随从、马腹汗湿带霜，确系只身仓皇夜逃"},{"id":"clue_family_arrest","label":"邺城细作密报审配已收捕许攸妻子家眷，袁营内讧坐实"}]},{"speaker":"xuyou","sourceTag":"史载","text":"（在门外急声叩栅，面上仍竭力维持故交体面）孟德！我许子远昔年洛阳旧交，今见袁本初刚愎不纳奇策，特来弃暗投明——快请开营叙话，我手上有破袁十万大军之机！"},{"speaker":"caohong","sourceTag":"推演","text":"（按剑拦在门内，神色冷峻）明公！此人贪而不治，当年便与袁绍同谋南下。眼下我军粮尽外困，安知不是袁绍演的苦肉计诱我开营、甚至引我往北伏击？军议先呈上来，请司空验过再开不开门！"},{"speaker":"cao","sourceTag":"暗忖","text":"许子远这个人嘴上永远挂着三分傲气，连逃命都还要摆出「择木而栖」的架子。先把他门外这番投奔呈词里的两处虚实剥开，再决定是赤足迎进账里，还是锁起来审问。"}],"interaction":{"type":"counter_case","title":"帅案核验","docTitle":"《许子远夜奔投效口供》","prompt":"用刚才北门外亲见与邺城密报，拆穿许攸话里遮掩的两层实情：","minExpose":2,"claims":[{"id":"c4_motive","surface":"「许子远素仰司空明德，故舍河北高爵厚禄，从容择主南来。」","proof":"他哪是什么从容择主？邺城密报刚到——审配在邺城抓了他的妻子家眷，袁绍又斥他贪而不治！他是走投无路才逃命，正因与袁营结了死仇，反倒绝不会回头卖我！","requiredClueId":"clue_family_arrest","effects":[{"kind":"var_add","var":"clues_found","delta":1}]},{"id":"c4_bluff","surface":"「今夜宜先摆出我军粮足可守之势，再缓缓议定河北虚实。」","proof":"单衣无随从、瘦马满腹带霜，这分明是半夜只身死逃出来的急客！他早就把袁营的底摸透了——待会儿一问军粮，拿「{{subtext:yi_yu_sui}}」绝对糊弄不住这位老熟人。","requiredClueId":"clue_frost_mud","effects":[{"kind":"var_add","var":"clues_found","delta":1}]}]},"choices":[{"id":"approve","label":"【{{gloss:xizu_yingyou}} · 抚掌尽信】不及穿履赤足迎入大帐，笑纳其言坦告实粮","hint":"军粮 -1 · 袁军合围 +1","isBait":true,"stampKind":"approve","stampText":"跣足迎攸","replyText":"（连鞋袜都顾不上穿，大笑着赤足奔出营门握住许攸双臂）子远远来，吾事济矣！孤这官渡大营——别人不能进，唯独你许子远今夜直接坐进中军帅座！","effects":[{"kind":"var_set","var":"c4_mode","value":"trust"},{"kind":"var_add","var":"canon_score","delta":1},{"kind":"resource","resource":"grain","delta":-1,"reason":"连夜筹备出奇突袭干粮并安顿降客，官渡存粮压至最后底线"},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"战局行至决死一夜，袁军合围亦已合拢至极点"}],"next":"N04_branch_trust"},{"id":"reject","label":"【疑为反间 · 扣押严审】先锁入偏帐严词盘问，待外哨查实真伪再作计较","hint":"钱帛 +0 · 袁军合围 +1","stampKind":"reject","stampText":"扣押严审","interestNote":"代价：严审耽搁今夜最佳突袭时辰，袁军合围迫近（死线 +1），且先机已失","replyText":"故交归故交，三万弟兄的性命不能赌在一个夜半敲门的人嘴上！先请许先生进偏帐歇息——传令外哨细作连夜潜往故市方向核实，未查明前，兵马一卒不动！","effects":[{"kind":"var_set","var":"c4_mode","value":"suspect"},{"kind":"var_add","var":"audit_score","delta":1},{"kind":"deadline","deadline":"yuanshao_siege","delta":1,"reason":"审讯核实拖过初更奇袭窗口，袁军合围逼至极限"}],"next":"N04_branch_suspect"},{"id":"whatif_frame_zhanghe","label":"【架空】疑许攸有诈，反手把「张郃高览通曹」的假密报送给袁绍","hint":"平行世界线 · 主动引爆袁营将帅内讧","stampKind":"dirty","stampText":"离间","replyText":"许子远嘴里真假难辨，但袁本初耳根软、郭图善妒却是千真万确！与其赌乌巢，不如直接把张郃、高览逼到我这边来！","effects":[{"kind":"resource","resource":"coin","delta":-1,"reason":"重金买通袁营降卒投递伪造书信"}],"next":"N_WI_frame_zhanghe"}]},"N04_branch_trust":{"id":"N04_branch_trust","act":"案肆支线 · 帐中问粮","title":"「实支一月耳！」","kind":"scene","mood":"fire","refs":["ref_xuyou_barefoot"],"lines":[{"speaker":"xuyou","sourceTag":"史载","text":"（入座后直视你的眼睛，压低声音）袁氏军盛，何以待之？今卿军粮尚有几何？"},{"speaker":"cao","sourceTag":"史载","text":"（顺口试探）「{{subtext:yi_yu_sui}}。」许攸大笑「无是，更言之」；孤退称可支半年，攸敛容怒问「足下欲全敌而何欺人甚也？」——孤屏退左右，苦笑答道：**「实支一月耳。」**"},{"speaker":"xuyou","sourceTag":"史载","text":"（猛一拍膝）孤军四面受敌而粮尽如此，危在旦夕！**今袁氏辎重有万余乘，在故市、**{{gloss:wuchao}}**，**{{subtext:qunjin_shi}}**！今以轻兵袭之，不意而至，燔其积聚，不过三日，袁氏自败也！**"},{"speaker":"xunyou","sourceTag":"推演","text":"（眼神骤亮，与贾诩对望一眼）文若所言「必将有变」，就在今夜！可曹洪却担心主力一旦夜出，官渡大营若被袁将反扑怎么守——诸将已在中军候令！"}],"next":"N05_case5"},"N04_branch_suspect":{"id":"N04_branch_suspect","act":"案肆支线 · 偏帐寒审","title":"审出了真情报，也熬过了半宿霜","kind":"scene","mood":"tense","refs":["ref_xuyou_barefoot"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"偏帐灯下 · 四更将尽","text":"几轮盘问到四更天，许攸气得拍案痛骂审配全家，终于吐出故市、乌巢屯有袁军万余乘粮车、淳于琼只顾喝酒毫无严备。可待派出去查探的夜哨快马赶回证实无误时，东方天际已经微微泛青——**初夜最佳的潜行窗口已然错失**。"},{"speaker":"xuyou","sourceTag":"推演","text":"（面色铁青）明公审得真是仔细！再过两个时辰天就大亮，五千人马出营必被袁营哨骑咬住尾巴！此刻要还去抢烧乌巢，已是强行冲阵血拼；若不敢动，便只剩死守官渡一途！"},{"speaker":"caohong","sourceTag":"推演","text":"虽迟了半宿，乌巢万乘军粮却千真万确。明公是咬牙强行补袭，还是彻底不动奇兵、把全部精锐留下来死扛官渡？"}],"choices":[{"id":"suspect_late_raid","label":"【错峰补袭】虽失初更先机，仍急集五千步骑赶在黎明前强袭乌巢","hint":"兵力 -1 · 进入乌巢军议（已失先手）","stampKind":"approve","stampText":"强行补袭","replyText":"迟了半宿也比坐等断粮强！急点步骑五千披袁旗赶赴乌巢——就算天明强攻折损大些，也要把这把火点起来！","effects":[{"kind":"var_set","var":"raid_delayed","value":true},{"kind":"resource","resource":"troops","delta":-1,"reason":"天明前仓促出营冲过袁军外哨遭遇截杀减员"}],"next":"N05_case5"},{"id":"suspect_hold_camp","label":"【疑而不袭】天明难保隐蔽，终恐堕入伏圈——撤消夜袭死守官渡大营","hint":"钱帛 -1 · 放弃乌巢奔袭 · 死守待局","stampKind":"reject","stampText":"按兵固守","replyText":"天色将明，五千主力离营百里若中伏，官渡瞬间即崩！赏赐将士严守深堑，只遣小股游骑沿河截烧袁军零散粮车——稳住营盘才是正道！","effects":[{"kind":"var_set","var":"raid_abandoned","value":true},{"kind":"resource","resource":"coin","delta":-1,"reason":"加发死守重赏激励官渡全营固壁迎敌"}],"next":"N05_case5"}]},"N05_case5":{"id":"N05_case5","act":"案伍 · 五千精骑夜袭乌巢","title":"《夜袭乌巢军议》","kind":"scene","mood":"fire","refs":["ref_wuchao_raid"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"巡营所见 · 决战前夜 · 前哨急报与乌巢舆图","text":"两批死士斥候刚从寒雾里翻下马来，带回截然相反的两头消息：东北四十里外的{{gloss:wuchao}}粮屯外只有几堆快熄的冷灶，守将**淳于琼**正拉着部将在中帐猜拳饮酒，十里外全无游骑；可官渡正北的袁军大营却灯火通明——大将{{gloss:zhanghe_gaolan|张郃、高览}}已把云梯与攻城冲车推到外壕边，显是只要你抽兵出营，他们便要全力反扑官渡本垒！","clues":[{"id":"clue_wuchao_lax","label":"乌巢仅余冷灶，淳于琼中帐酣饮毫无防备"},{"id":"clue_zhanghe_camp","label":"张郃高览云梯冲车已抵官渡外壕，只等曹军分兵空虚"}]},{"speaker":"caohong","sourceTag":"推演","text":"（指着沙盘上的《夜袭乌巢军议》急切请示）明公！五千步骑一抽，本营就只剩我们几千疲卒顶着张郃、高览！若袁绍听说乌巢遇袭却不回救、反令主力猛攻官渡，我等孤营怎么扛得住？"},{"speaker":"xunyou","when":{"var":"raid_abandoned","op":"==","value":false},"sourceTag":"史载","text":"（按住沙盘）正是{{subtext:dang_gong_benying}}！袁绍只肯派轻骑零散援琼，主力定压来官渡——只要洪与攸死扛半夜本营，明公在乌巢绝不可分兵回救！"},{"speaker":"xunyou","when":{"var":"raid_abandoned","op":"==","value":true},"sourceTag":"推演","text":"（望向沙盘长叹）前番虽按住未袭，眼下张郃冲车已压近壕边，合围只在旦夕——是就地死扛游骑截粮、使非常焦土之策，还是趁大营未合围前全师退保许都，就在这一印之间！"},{"speaker":"cao","sourceTag":"暗忖","text":"这半年的官渡血账，全压在最后这一纸军议上。先把诸将呈文里藏着的两处怯战托词捅破，再挥出最后一印！"}],"interaction":{"type":"counter_case","title":"帅案核验","docTitle":"《夜袭乌巢军议》","prompt":"用斥候带回的乌巢与北营实情，点破军议中动摇军心的两句怯言：","minExpose":2,"claims":[{"id":"c5_chunyu","surface":"「乌巢屯粮万余乘乃袁军命脉，淳于琼素为宿将，必设重伏以待。」","proof":"斥候潜到木栅外十步看得真真切切：淳于琼正脱了甲在中帐灌酒，外围只有几堆冷灶，十里内连个游骑哨声都听不见！","requiredClueId":"clue_wuchao_lax","effects":[{"kind":"var_add","var":"clues_found","delta":1}]},{"id":"c5_zhanghe","surface":"「若前军遭袁军骑兵援救或张郃猛攻本营，主帅当即分兵回师接应。」","proof":"张郃、高览把冲车排在外壕边正是想拖住主力不敢出击；一旦袭粮途中遇到援骑还想着分兵回头，乌巢烧不着、本营也必溃——唯有一往无前死战烧粮，张郃那边自然不攻自乱！","requiredClueId":"clue_zhanghe_camp","effects":[{"kind":"var_add","var":"clues_found","delta":1}]}]},"choices":[{"id":"approve","label":"【五千夜袭 · 绝不回救】冒{{gloss:xianmei_yuanqi}}亲奔乌巢，留曹洪荀攸守营，遇援死战不回","hint":"军粮 -1 · 兵力 -1 · 袁军合围 -2","isBait":true,"when":{"var":"raid_abandoned","op":"!=","value":true},"stampKind":"approve","stampText":"亲袭乌巢","replyText":"留曹洪、荀攸死守官渡本营！乐进随孤亲率步骑五千，全换袁军旗帜、人衔枚马缚口，连夜从间道直扑乌巢！凡遇袁军盘问，便答袁公遣兵益备——到了乌巢，就是贼杀到背后也绝不许回头！","effects":[{"kind":"var_set","var":"c5_mode","value":"raid_canon"},{"kind":"var_add","var":"canon_score","delta":1},{"kind":"resource","resource":"grain","delta":-1,"reason":"五千精骑轻装急行抛下后方輜重口粮"},{"kind":"resource","resource":"troops","delta":-1,"reason":"乌巢营外血战淳于琼及拒后援精锐伤亡"},{"kind":"deadline","deadline":"yuanshao_siege","delta":-2,"reason":"火烧乌巢万余乘粮车彻底击穿袁军合围"}],"next":"N06_climax"},{"id":"grit_hold","label":"【固垒硬熬 · 游骑截粮】主力不动死抗张郃强攻，只遣小股轻骑袭扰袁军粮道","hint":"军粮 -1 · 兵力 -1 · 袁军合围 +0","stampKind":"reject","stampText":"固垒硬熬","interestNote":"代价：放过决胜一把火，全靠血肉和最后口粮拖入冬雪拉锯","replyText":"孤不能拿官渡大营全军性命赌这一夜孤注！全军原地死扛张郃、高览攻势，另遣数百游骑潜去故市、乌巢外围焚掠零散运车——看是他的十万大军先饿散，还是孤先撑不住！","effects":[{"kind":"var_set","var":"c5_mode","value":"grit_hold"},{"kind":"var_add","var":"audit_score","delta":1},{"kind":"resource","resource":"grain","delta":-1,"reason":"死守孤垒耗尽最后一批库底余粮"},{"kind":"resource","resource":"troops","delta":-1,"reason":"正面硬接张郃高览连日昼夜强攻折损"}],"next":"N06_climax"},{"id":"dirty","label":"【诈降诱陷 · 焦土断援】假弃外营诱张郃入陷坑，同时遣死士火焚乌巢连带周边村屯","hint":"军粮 -1 · 兵力 -1 · 袁军合围 -1","stampKind":"dirty","stampText":"焦土破袁","interestNote":"⚠ 极重代价：毒井焚屯连坐河南百姓，纵破袁绍亦将令士族与黎民彻骨寒心","replyText":"既要绝袁氏粮草，便连方圆三十里的秋收村屯一并放火烧净、井水投秽！官渡外寨故作空营诱张郃半夜抢入火陷坑——活路是自己杀出来的，名声留给史官去写！","effects":[{"kind":"var_set","var":"c5_mode","value":"dirty_scorch"},{"kind":"var_add","var":"dirty_count","delta":1},{"kind":"resource","resource":"grain","delta":-1,"reason":"实施焦土断绝周边补给亦自断官渡采买余地"},{"kind":"resource","resource":"troops","delta":-1,"reason":"诈营诱陷与越境焚屯死士十去六七"},{"kind":"deadline","deadline":"yuanshao_siege","delta":-1,"reason":"烈焰毒烟与火坑重创逼退袁军围阵"},{"kind":"dirty_trick","id":"dt_scorch_earth","label":"火焚村屯＋毒井焦土破袁","interest":"彻底击垮袁军补给却烧尽河南民心，士林皆畏曹氏冷酷"}],"next":"N06_climax"},{"id":"retreat","label":"【全师退保许都】军粮已尽、合围难破，留精锐断后趁夜全军撤返许都","hint":"军粮 -1 · 兵力 -1 · 放弃官渡防线","stampKind":"reject","stampText":"退保许都","interestNote":"代价：主动放弃官渡咽喉退回许都，河北四州霸业将落入袁绍之手","replyText":"打到今日，孤对得起荀文若，也对得起手里这不到两万弟兄！弃掉不可带走的笨重器物，全师趁夜有序撤保许都——只要中原根基还在，总有卷土重来之日！","effects":[{"kind":"var_set","var":"c5_mode","value":"retreat"},{"kind":"resource","resource":"grain","delta":-1,"reason":"仓促撤营焚毁余粮轻装退保许都"},{"kind":"resource","resource":"troops","delta":-1,"reason":"夜撤时留精锐断后掩护遭袁骑追击折损"}],"next":"N06_climax"},{"id":"whatif_raid_ye","label":"【架空】不烧乌巢！五千精骑打袁军旗号，绕过黄河直捣空虚邺城","hint":"平行世界线 · 疯狂千里奔袭老巢","stampKind":"dirty","stampText":"袭邺","replyText":"烧了乌巢袁绍还能逃回河北东山再起！既然要赌，就赌把大的——五千虎豹骑随孤偷渡黄河，直插袁绍的老巢邺城！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"轻骑携三日干粮奔袭河北腹地"}],"next":"N_WI_raid_ye"}]},"N06_climax":{"id":"N06_climax","act":"陆 · 官渡终局战报","title":"乌巢天火与百年基业账","kind":"scene","mood":"fire","refs":["ref_wuchao_raid","ref_burn_letters"],"lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年十月 · 官渡与乌巢之间","text":"寒霜夜里每一张落过印的军令、每一口勒着裤腰咽下去的薄粥，都在这一夜黎明前同时亮出了底牌。"},{"speaker":"narrator","when":{"var":"c1_mode","op":"==","value":"seal"},"sourceTag":"结语","text":"【案壹回执】你把七封暗通袁绍的密信锁进了铁匣底——破敌前未杀一人、未惊一营，让这孤垒里的人心安安稳稳熬过了最黑的半夜。"},{"speaker":"narrator","when":{"var":"c2_mode","op":"==","value":"small_hu"},"sourceTag":"结语","text":"【案贰回执】你在只剩一个月的粮底上咬牙压下日配，把稀粥硬生生拉长熬过了许攸夜奔的那个子夜。"},{"speaker":"narrator","when":{"var":"c3_mode","op":"==","value":"counter"},"sourceTag":"结语","text":"【案叁回执】霹雳车砸垮了土山高橹、内侧长堑吞掉了地道兵，你才得以保存完好的大营接下十月那场天赐内变。"},{"speaker":"narrator","when":{"all":[{"var":"c5_mode","op":"==","value":"raid_canon"},{"var":"raid_delayed","op":"==","value":false}]},"sourceTag":"史载","text":"【乌巢烈焰】黎明前五千精骑团团围住乌巢，四面纵火！袁军轻骑急援至背后，部将喊着请分兵，你厉声喝出一句「{{gloss:zeizai_beihou}}**，乃白！**」士卒无不殊死拼命，生擒斩杀淳于琼、尽焚万余乘粮谷！官渡营外久攻不下的{{gloss:zhanghe_gaolan}}闻风恐遭郭图谗害，尽焚攻具率众归降；袁绍仓惶弃军，仅以八百骑渡河北逃！"},{"speaker":"narrator","when":{"all":[{"var":"c5_mode","op":"==","value":"raid_canon"},{"var":"raid_delayed","op":"==","value":true}]},"sourceTag":"推演","text":"【迟来一火】因为审讯许攸误了初更天时，五千精骑赶到乌巢时已是天色大白。血战付出更重代价才烧毁半数粮屯，袁绍虽惊怒撤围却仍保有大半建制退回黎阳，未能一战全溃河北。"},{"speaker":"narrator","when":{"var":"c5_mode","op":"==","value":"grit_hold"},"sourceTag":"推演","text":"【冬雪拖退】你固守官渡长堑死扛张郃强攻，又派游骑连日袭烧袁军后方零散粮队。入冬大雪封道后袁绍十万之众无食可继、内讧四起，不得不拔寨退保河北——你保住了许都与官渡，却没能一战吃掉袁氏精华。"},{"speaker":"narrator","when":{"var":"c5_mode","op":"==","value":"dirty_scorch"},"sourceTag":"推演","text":"【焦土血胜】火陷坑吞了张郃前锋，三十里焦土与秽井逼得袁军饿溃北遁——官渡赢了，可河北与中原世族连夜传遍曹氏狠毒之名，往后十年的征召和安抚，都要替今夜买单。"},{"speaker":"narrator","when":{"var":"c5_mode","op":"==","value":"retreat"},"sourceTag":"推演","text":"【夜撤许都】大营篝火未熄，主力已沿着汴水夜道退回许都。官渡防线空留给袁绍，好在两万老底尚在，接下来只能在许昌城下重开一局更苦的保卫战。"},{"speaker":"cao","sourceTag":"结语","text":"天亮了。去清点那些留在铁匣子里的信、灰烬里的粮车，看看这一局官渡替你写出了怎样的北方天命。"}],"next":[{"when":{"var":"c5_mode","op":"==","value":"retreat"},"next":"E_guandu_retreat"},{"when":{"any":[{"var":"c5_mode","op":"==","value":"dirty_scorch"},{"var":"dirty_count","op":">=","value":2}]},"next":"E_guandu_dirty"},{"when":{"all":[{"var":"c5_mode","op":"==","value":"raid_canon"},{"var":"raid_delayed","op":"==","value":false}]},"next":"E_guandu_canon"},{"next":"E_guandu_grit"}]},"E_guandu_canon":{"id":"E_guandu_canon","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"史实奇胜 · 乌巢烈火定河北","title":"十分居一熬到内变，五千死士一把火烧穿北方天下","subtitle":"你忍住了不抓内鬼、压住了一月残粮、拆掉了土山地道，在故友赤足敲门那一刻押上了全部筹码。","tone":"ok","verdict":"乌巢万乘军粮化作漫天红光，张郃高览阵前归降，袁绍仅以八百骑遁归河北。曹操尽焚缴获之许下与军中通袁密信曰「当绍之强，孤犹不能自保，而况众人乎」，北方大局遂定。","careerSeed":"《三国志·武帝纪》官渡奇胜正轨终局","buildName":"绝境孤赌流 · 先熬底线再烧命门","buildQuote":"「前期每一刀都忍在袖子里不肯乱挥，只为了天亮前喊出那句『贼在背后，乃白！』」"}},"E_guandu_grit":{"id":"E_guandu_grit","kind":"ending","mood":"cold","lines":[],"ending":{"badge":"苦守熬退 · 保许再图","title":"没敢（或迟了一步）全押乌巢，靠两只铁拳生生把十万大军熬回河北","subtitle":"你没有写出最惊艳的五千奇袭神话，却硬凭深堑死守与克制用兵守住了许都与北方脊梁。","tone":"info","verdict":"曹军保住官渡至许都防线，袁绍久攻不克、粮运耗尽而在入冬后退兵黎阳；北方虽未一战定鼎，但曹氏基业安稳度过建安五年最大生死劫。","careerSeed":"南北对峙于黄河渡口，来年再争河北","buildName":"苦熬铁壁流 · 不求一战封神但求绝不翻车","buildQuote":"「赢法不花哨，甚至有点憋屈——可对岸十万人熬不起的寒冬，我偏熬得起。」"}},"E_guandu_dirty":{"id":"E_guandu_dirty","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"毒计破袁 · 众叛亲离","title":"袁绍的大军是被打散了，可帐里帐外看向你的眼神全冷透了","subtitle":"仿信设阱、强抄世族、焦土秽井——每一手脏活都替你换回了筹码，也一笔一笔把人心赔了个干净。","tone":"warn","verdict":"虽于官渡惨胜逼退袁氏，但许颍豪强、留守士林乃至营中旧将皆寒心畏惧；后续经略河北时人心难附，处处须靠严刑高压维系。","careerSeed":"霸业存而德望折损，高利贷利息连年兑现","buildName":"枭雄暗账流 · 赢在当下而输尽来日人情","buildQuote":"「活着走出了官渡，只是从此铁匣子里的信不敢烧、背后递来的茶也不敢轻易喝了。」"}},"E_guandu_retreat":{"id":"E_guandu_retreat","kind":"ending","mood":"cold","lines":[],"ending":{"badge":"退保许都 · 痛失河北","title":"在断粮与合围里先眨了眼，带回老底却把官渡咽喉让给了袁绍","subtitle":"正如荀彧信中所言「先退者势屈也」——保住了两万精锐性命，也亲手关上了五年定北方的大门。","tone":"danger","verdict":"曹军弃官渡退保许都，袁绍趁势跨河南下连结刘表、经略豫兖，天下重陷漫长苦战，曹氏霸业推迟十余年。","careerSeed":"退守许昌孤城，迎战乘胜南压的河北联军","buildName":"止损保本流 · 保住了人马却输掉了大势","buildQuote":"「退回家门当然比葬在土垒里稳当——只是袁本初不会给你第二次修官渡的机会。」"}},"E_collapse_coin":{"id":"E_collapse_coin","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"红线崩盘 · 府库告罄","title":"行营钱帛归零，连连夜巡哨的赏帛都开成了空头券","subtitle":"工匠拆不下木料、门吏守不住驿卡——没等袁军填平外壕，内帐先把算盘摔碎了。","tone":"danger","isCollapse":true,"verdict":"随军钱帛耗竭归零触发红线崩盘，赏罚失灵、防务停摆，官渡大营从内部率先溃散。"}},"E_collapse_grain":{"id":"E_collapse_grain","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"红线崩盘 · 断粮营啸","title":"最后一口榆皮粥也刮光了锅底，夜半营啸炸响在北垒前","subtitle":"军粮归零——官渡最致命的倒计时终究跑在了许攸来奔与奇袭之前。","tone":"danger","isCollapse":true,"verdict":"军粮耗竭归零触发红线崩盘，三军断炊饥溃，不战而退散官渡。"}},"E_collapse_troops":{"id":"E_collapse_troops","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"红线崩盘 · 兵力折尽","title":"高垒深堑还在，站在垛口拿矛的人数不过两指","subtitle":"兵力归零——清查逃散、抢修血耗与无谋强攻榨空了最后一营老卒。","tone":"danger","isCollapse":true,"verdict":"可战兵力耗尽触发红线崩盘，守垒人数不足致官渡全线失守。"}},"E_collapse_multi":{"id":"E_collapse_multi","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"红线崩盘 · 全面崩塌","title":"钱、粮、兵同拍见底，寒霜夜里的孤垒瞬间失重","subtitle":"多项核心军政指标在同一道军令下同时归零——再高的用兵算计也兜不住彻底空掉的家底。","tone":"danger","isCollapse":true,"verdict":"多项核心资源同时耗竭崩盘，官渡防线一夜全面瓦解。"}},"E_deadline_overflow":{"id":"E_deadline_overflow","kind":"ending","mood":"fire","lines":[],"ending":{"badge":"死线爆表 · 袁军合围","title":"每一步都求稳让地、反复迟疑，抬头时十万连营已把官渡焊死","subtitle":"袁军合围拉满 6/6——你在垒内拖得越慎，袁绍的高橹、长围与骑兵封锁就锁得越死。","tone":"danger","isDeadlineOverflow":true,"verdict":"一路退让拖延耗尽腾挪空间，被袁军彻夜合围切断全部外路，官渡孤垒困毙失守。","buildName":"畏战迟延流 · 账面滴水不漏却把门缝让给了合围","buildQuote":"「十分居一最怕的不是拼命，而是你每让一步，十万人的包围圈就替你收紧一寸。」"}},"N_WI_xudu_march":{"id":"N_WI_xudu_march","act":"架空支线 · 弃垒回师许都","title":"许都城下的豪赌","kind":"scene","mood":"tense","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年冬 · 许都北门","text":"官渡孤垒一夜人去楼空。袁绍大喜过望，不顾沮授劝阻挥十万大军渡过汴水长驱南下，一路直逼许都百里之内——却也在泥泞秋雨中把自己的河北粮道拉长到了三百里。"},{"speaker":"xunyu","sourceTag":"推演","text":"丞相既已退回许都，中原郡县半数观望，此刻再退一步便真成流寇！唯今之计，只有依托许都坚城死守，趁袁军粮道拉长、兵骄将惰之际，遣精骑反插其背！"},{"speaker":"xunyou","sourceTag":"推演","text":"许都尚有半年积粮，但城中汉室旧臣蠢蠢欲动。若袁军合围许都，内忧外患齐发，也有幕僚建言暂奉天子西迁洛阳以避锋芒。"},{"speaker":"cao","sourceTag":"拟写","text":"退到许都是我主动卖的破绽，现在袁本初的脖子已经伸到我刀口底下了——守，还是迁？"}],"choices":[{"id":"wi_xudu_counter","label":"坚壁许都，遣乐进、曹洪轻骑绕后烧断河北三百里粮道","hint":"兵力 -1 · 反客为主一战定局","stampKind":"approve","stampText":"断粮","replyText":"天子一步不迁！许都城墙由孤亲自守，乐进、曹洪带三千轻骑给我绕到延津去烧袁绍的屁股！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"抽调三千精骑远袭敌后粮道"}],"next":"E_WI_xudu_counter"},{"id":"wi_luoyang_move","label":"奉天子西迁洛阳旧都，依托函谷关与袁绍打十年持久战","hint":"粮草 -1 · 中原易主换取生机","stampKind":"reject","stampText":"西迁","replyText":"许都四战之地难挡十万大军，连夜护驾西入洛阳，凭山河之险与袁本初慢慢耗！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"仓促迁都丢弃许都半数存粮"}],"next":"E_WI_luoyang_split"}]},"E_WI_xudu_counter":{"id":"E_WI_xudu_counter","act":"架空结局 · 许都坚壁","title":"许都城下，反客为主","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安六年春 · 延津火光","text":"袁绍围攻许都四十日不下，反因三百里粮道被乐进轻骑连烧七处而全军断炊。冬雪降临前，十万河北大军在许都城外不战自溃——官渡未曾烧起的乌巢火，换成了延津沿岸连绵百里的焦土。"}],"ending":{"badge":"架空支线 · WHAT-IF","title":"许都坚壁，反客为主","subtitle":"以空间换粮道 · 另一种官渡大胜","tone":"ok","verdict":"你冒着中原震动的巨大风险放弃官渡，却把「缺粮」的死穴原封不动转嫁给了拉长战线的袁绍。背靠许都积粮，反手以轻骑切碎三百里补给线，走出了一条史书未载的奇胜之路。","buildName":"诱敌深入反杀派","buildQuote":"谁说一定要在官渡等许攸？把袁本初请到许都城下饿三天也一样。"}},"E_WI_luoyang_split":{"id":"E_WI_luoyang_split","act":"架空结局 · 河洛再裂","title":"天子西迁，河洛崩析","kind":"ending","mood":"cold","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安六年 · 洛阳残垣","text":"你保住了主力与天子，却把肥沃的兖豫中原拱手让给了袁绍。群雄见曹军西退，纷纷改换门庭。站在洛阳荒草丛生的宫城上，你虽未覆灭，却再也回不到逐鹿中原的牌桌中央。"}],"ending":{"badge":"架空支线 · WHAT-IF","title":"天子西迁，北方再裂","subtitle":"保全性命却失中原 · 历史彻底改道","tone":"warn","verdict":"正如荀彧当初所警：官渡退一步是许都，许都再退一步便是万劫不复。你避开了覆灭的惨局，却也亲手把北方霸权推到了袁氏手中。","buildName":"保全实力西迁派","buildQuote":"人还活着，天子还在手，只是中原从此改姓了袁。"}},"N_WI_fake_defect":{"id":"N_WI_fake_defect","act":"架空世界线 · 西门假降夜伏","title":"三更燃起的西门火把","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年秋 · 官渡西门三更","text":"袁绍果然中计，遣大将淳于琼与河北万余精锐衔枚夜袭西门。三声梆子响过，西门如约洞开，袁军先锋蜂拥涌入——等待他们的不是内应，而是四面合围的火油沟与连弩阵！"},{"speaker":"yuejin","sourceTag":"推演","text":"丞相！袁军先锋已被困死在西门瓮城，外面袁绍中军见火光冲天，正乱成一团不知真假！此时既可全歼瓮城精锐，也可换穿袁军衣甲顺势反冲袁绍大本营！"}],"choices":[{"id":"wi_trap_vanguard","label":"关门打狗，全歼入瓮的万余河北精锐再顺势缴粮","hint":"粮草 +1 · 稳吃袁军半壁主力","stampKind":"approve","stampText":"关门","replyText":"先把嘴里这口肥肉咬死！全歼西门袁军，把他们带的干粮兵甲统统扒下来！","effects":[{"kind":"resource","resource":"grain","delta":1,"reason":"缴获夜袭袁军大批随身干粮与马匹"}],"next":"E_WI_trap_vanguard"},{"id":"wi_assassinate_yuan","label":"留曹洪收尾，亲率乐进换袁军旗号夜闯袁绍中军斩旗","hint":"兵力 -1 · 孤胆夜袭直取中军","stampKind":"dirty","stampText":"斩旗","replyText":"袁本初好谋无断，今夜混乱正是天赐良机！换上袁军号衣，随孤直冲中军大纛！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"敢死队强闯袁营中军血战折损"}],"next":"E_WI_assassinate_yuan"}]},"E_WI_trap_vanguard":{"id":"E_WI_trap_vanguard","act":"架空结局 · 西门瓮城","title":"一战折尽河北先锋","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年秋 · 官渡黎明","text":"天明时，官渡西门外尸横遍野，袁军最精锐的夜袭万余人几乎全军覆没。袁绍惊怒交加，再也不敢轻信营中密报，士气一落千丈，官渡之战提前两个月分出了胜负。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"官渡夜伏，一战折袁军半壁","subtitle":"借通敌密信反杀 · 未等乌巢先破敌","tone":"ok","verdict":"历史上曹操烧掉密信安抚了人心，而你更狠一步——把差点要你命的内鬼做成了钓杀袁绍精锐的鱼饵。","buildName":"借鬼钓敌大师","buildQuote":"写降信？写得好！再帮孤多写两句约个时间地点。"}},"E_WI_assassinate_yuan":{"id":"E_WI_assassinate_yuan","act":"架空结局 · 混营斩旗","title":"夜斩袁绍中军大纛","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年秋 · 河北大营残火","text":"乐进一刀砍倒袁绍帅旗时，十万袁军彻底陷入无主自相践踏的噩梦。袁绍只带八百亲骑仓皇渡河逃回邺城，当夜惊悸卧病，河北霸业就此崩塌。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"混营斩旗，袁绍惊病北逃","subtitle":"奇兵直捣中军 · 一夜定官渡","tone":"ok","verdict":"趁敌军以为内应得手的刹那反插心脏，你把一场漫长的消耗战打成了三国最狂野的斩首夜袭。","buildName":"中军斩首狂徒","buildQuote":"不用等许攸来报信，我自己去袁本初帐里拿粮。"}},"N_WI_frame_zhanghe":{"id":"N_WI_frame_zhanghe","act":"架空世界线 · 河北将帅反目","title":"郭图进谗，张郃寒心","kind":"scene","mood":"tense","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年冬 · 袁军前锋营","text":"你的假密报送到郭图手里不到半日，袁绍便暴怒传令召张郃、高览回中军对质。二将闻讯自知回去必死，连夜派心腹翻墙来官渡叩营求见！"},{"speaker":"xunyou","sourceTag":"推演","text":"张郃、高览手握河北最能打的两万精兵！此刻袁军前锋阵脚大乱：是立刻迎降二将直反袁绍中军，还是趁袁军换将群龙无首直接全军压上正面击溃？"}],"choices":[{"id":"wi_zhanghe_coup","label":"厚礼迎降张郃高览，令其作为前驱反杀袁绍大营","hint":"兵力 +1 · 河北名将提前归心","stampKind":"approve","stampText":"迎降","replyText":"张儁乂乃河北柱石！孤亲出营门执手迎降，今夜便由你领兵踏平郭图营寨！","effects":[{"kind":"resource","resource":"troops","delta":1,"reason":"张郃高览率河北精锐整建制归降"}],"next":"E_WI_zhanghe_coup"},{"id":"wi_frontal_crush","label":"趁袁军阵前换将混乱，全军鼓噪出垒正面碾压","hint":"粮草 -1 · 一鼓作气正面破袁","stampKind":"reject","stampText":"决战","replyText":"敌军阵前易帅乃兵家大忌！敲响全部战鼓，官渡诸营随孤正面杀出去！","effects":[{"kind":"resource","resource":"grain","delta":-1,"reason":"尽倾仓底余粮饱餐三军全线出击"}],"next":"E_WI_frontal_crush"}]},"E_WI_zhanghe_coup":{"id":"E_WI_zhanghe_coup","act":"架空结局 · 河北倒戈","title":"张郃反戈，袁营土崩","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年冬 · 官渡北原","text":"张郃、高览倒戈的旗帜在夜色中升起时，原本压在官渡头顶的十万大军瞬间崩溃。你没烧一粒乌巢的粮食，反而完整接手了河北大仓与最精锐的降将。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"张郃倒戈，反噬袁绍中军","subtitle":"不烧粮仓烧信任 · 完整接手河北精锐","tone":"ok","verdict":"攻心为上，攻城为下。你精准踩中了袁绍多疑、郭图善妒的死穴，一封假信直接帮自己换来了两万精兵与未来五子良将。","buildName":"反间挖角大师","buildQuote":"袁本初最值钱的不是乌巢的米，是张儁乂这把刀。"}},"E_WI_frontal_crush":{"id":"E_WI_frontal_crush","act":"架空结局 · 正面击溃","title":"阵前易帅，一鼓破十万","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年冬 · 官渡旷野","text":"趁着袁军前线换将交接的混乱时刻，饱餐最后一顿干粮的曹军如猛虎出笼，从正面撕穿了袁绍的连营。以两万正面击溃十万的奇迹，从此载入兵家史册。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"临阵换将大乱，官渡正面击溃","subtitle":"抓准敌营一瞬空档 · 正面决胜","tone":"ok","verdict":"没有偷袭、没有火攻，你在敌军指挥体系短暂瘫痪的那个时辰押上了全部家底，打出了最硬核的正面翻盘。","buildName":"硬刚正面破局派","buildQuote":"谁说以弱胜强只能偷粮？他换将那一刻就是死期。"}},"N_WI_raid_ye":{"id":"N_WI_raid_ye","act":"架空世界线 · 千里奇袭邺城","title":"孤军突至邺城下","kind":"scene","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年冬 · 邺城南门","text":"五千曹军精骑一路打着袁军催粮旗号，昼伏夜出竟真摸到了防备空虚的邺城城下！城头守卒仓皇敲响警钟，袁氏宗族与河北百官一夜之间乱作一团。"},{"speaker":"caohong","sourceTag":"推演","text":"丞相！我军孤悬敌后，久留必遭河北各郡合围！是立刻放火烧光邺城总仓逼袁绍官渡大军回师自乱，还是趁乱抢占内城挟袁氏宗族逼袁绍阵前投降？"}],"choices":[{"id":"wi_burn_ye","label":"火烧邺城总库后迅速撤回，逼官渡十万袁军不战自溃","hint":"粮草 +1 · 稳赚不赔的战略大撤退","stampKind":"approve","stampText":"焚库","replyText":"抢满马袋干粮，一把火把袁绍的老家总仓点着！咱们拍拍屁股渡河回去看袁本初吐血！","effects":[{"kind":"resource","resource":"grain","delta":1,"reason":"抢掠邺城外仓补满轻骑给养"}],"next":"E_WI_burn_ye"},{"id":"wi_hostage_yuan","label":"强攻夺下邺城内城，挟袁氏宗族与四州印绶逼袁绍投降","hint":"兵力 -1 · 一战提前七年平河北","stampKind":"dirty","stampText":"夺城","replyText":"都杀到袁绍家门口了还走什么？夺下邺城铜雀台旧址，写信叫袁本初回来领全家老小！","effects":[{"kind":"resource","resource":"troops","delta":-1,"reason":"孤军强攻邺城内城巷战折损"}],"next":"E_WI_hostage_yuan"}]},"E_WI_burn_ye":{"id":"E_WI_burn_ye","act":"架空结局 · 火烧邺城","title":"后院起火，官渡袁军自溃","kind":"ending","mood":"fire","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安五年腊月 · 官渡南岸","text":"邺城冲天火光的消息传回官渡那日，十万袁军军心瞬间崩盘——家在河北的士卒纷纷丢盔弃甲往北奔逃。你兵不血刃解了官渡之围，连审配都叹服这手千里袭营简直神鬼莫测。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"奇袭邺城，袁绍后院起火","subtitle":"比乌巢更狂的千里奇袭","tone":"ok","verdict":"乌巢只是袁军的钱袋子，邺城才是袁军的命根子。你一把火烧掉了河北十万大军的归心，堪称古今第一奇兵。","buildName":"千里偷家之王","buildQuote":"烧乌巢格局小了，要烧就烧袁本初的老家。"}},"E_WI_hostage_yuan":{"id":"E_WI_hostage_yuan","act":"架空结局 · 挟邺定河北","title":"一战提前七年平定河北","kind":"ending","mood":"calm","lines":[{"speaker":"narrator","isWalk":true,"walkKicker":"建安六年春 · 邺城大堂","text":"邺城陷落的消息击垮了袁绍最后的意志。河北四州群龙无首，袁谭、袁尚尚未开争便已归降。历史上打了整整七年的平河北之战，被你一场疯癫而精准的豪赌一夜终结。"}],"ending":{"badge":"架空世界线 · WHAT-IF","title":"挟邺逼降，提前七年定河北","subtitle":"史上最狂豪赌 · 改写北方十年格局","tone":"ok","verdict":"这把赌注大到连郭嘉都不敢轻易点头，但你赌赢了——直接省去七年苦战，建安六年便已坐拥冀青幽并四州。","buildName":"天命豪赌曹操","buildQuote":"兵法说孤军深入必死？可我直接坐在了袁绍的太师椅上。"}}}`),y=[{title:`一、七封通袁密信：战前暂压，破袁后尽焚`,when:{var:`c1_mode`,op:`==`,value:`seal`},canonNote:`《三国志·武帝纪》载「及破绍，得许下及军中人书，皆焚之。曰：『当绍之强，孤犹不能自保，而况众人乎！』」`,playerHit:`你没有在绝境前夜抓人清营，而是把信封进铁匣稳住军心，再现了曹公最顶级的御下定力。`,playerMiss:`你选择了连夜清查抓人或仿写假信反钓，虽解一时心气，却在战前掀动了军中暗流。`},{title:`二、官渡断粮：只剩一月，咬牙缩配死守`,when:{var:`c2_mode`,op:`==`,value:`small_hu`},canonNote:`《武帝纪》载「公军粮方尽，与荀彧书，议欲还许」；《荀彧传》载「扼其喉而不得进，已半年矣」，正靠极限压配熬到生变。`,playerHit:`你在七折小斛与沙土假袋面前忍下苦果，用极限节衣缩食硬拖出了破局时间窗。`,playerMiss:`你改用常额公摊放任余粮剧减，或强征许颍世族藏粮，改写了官渡后勤的抗压线。`},{title:`三、土山高橹与地道：霹雳车、长堑反制`,when:{var:`c3_mode`,op:`==`,value:`counter`},canonNote:`《武帝纪》载「太祖乃为发石车，击绍楼，皆破，绍众号曰霹雳车。绍为地道，欲袭太祖营。太祖辄于内为长堑以拒之」。`,playerHit:`你如正史般咬牙砸出霹雳车与内长堑，在钱粮捉襟见肘时依然寸土不让。`,playerMiss:`你舍不得工本而弃守外垒退缩中军，结果把土山高橹推到了自己粮棚头顶。`},{title:`四、许攸夜奔：不及穿履，跣足出迎`,when:{var:`c4_mode`,op:`==`,value:`trust`},canonNote:`《武帝纪》裴注引《曹瞒传》载「公闻攸来，跣出迎之，抚掌笑曰：『子卿远来，吾事济矣！』」，并坦告「实支一月耳」。`,playerHit:`你从审配收捕家眷与满腹霜泥里看透了许攸的死仇，赤足出迎果断押上了整个官渡赌局。`,playerMiss:`你疑心许攸为袁营反间而将其扣押严审，错过了初更夜奔的第一重奇袭天时。`},{title:`五、五千步骑夜袭乌巢：「贼在背后，乃白！」`,when:{var:`c5_mode`,op:`==`,value:`raid_canon`},canonNote:`《武帝纪》载留曹洪荀攸守营、自将步骑五千夜攻淳于琼；援骑在后请分兵，操怒曰「贼在背后，乃白」，张郃高览遂降。`,playerHit:`你冒用袁旗衔枚夜驰、面对背后援骑绝不分兵，用五千死士彻底烧垮了袁氏十万根基。`,playerMiss:`你选择固垒硬熬、焦土毒计或退保许都，走出了与乌巢大火截然不同的北方走势。`},{title:`六、终局对照：建安五年官渡定鼎`,when:{visited:`E_guandu_canon`},canonNote:`建安五年十月乌巢火起，袁绍弃军北渡，曹操由此奠定统一北方之基。`,playerHit:`你的每一拍抉择都压准了《三国志》官渡绝境的脉搏：十不敌一不是靠兵法幻术赢的，而是一步一步把底线熬穿熬透。`,playerMiss:`你凭借保守固守、冷酷权谋或及时止损改写了建安五年秋夜的结局，走出属于另一种取舍的官渡旁支。`}],b={schemaVersion:1,id:t,version:n,title:r,subtitle:i,tagline:a,estimatedMinutes:14,theme:s,cast:c,varsSchema:l,resources:u,multiCollapseEndingId:d,deadlines:f,startNode:p,acts:m,gloss:h,subtexts:g,refs:_,nodes:v,historyDossier:y};export{m as acts,c as cast,f as deadlines,b as default,o as estimatedMinutes,h as gloss,y as historyDossier,t as id,d as multiCollapseEndingId,v as nodes,_ as refs,u as resources,e as schemaVersion,p as startNode,g as subtexts,i as subtitle,a as tagline,s as theme,r as title,l as varsSchema,n as version};